#       строка 2 - k (число строк фрагмента); далее k строк: c1 c2 c3 c4 F, клетки 0, 1 или - (пропуск).
# Выход: четыре буквы (порядок столбцов слева направо) или AMBIGUOUS / NONE.
import sys
from itertools import permutations

def main():
    data = sys.stdin.read().split("\n")
    col = [int(ch) for ch in data[0].strip()]
    k = int(data[1])
    rows = []
    for i in range(k):
        p = data[2 + i].split()
        rows.append(([None if c == "-" else int(c) for c in p[:4]], int(p[4])))
    pos = {"w": 3, "x": 2, "y": 1, "z": 0}          # номер бита в индексе набора
    good = []
    for perm in permutations("wxyz"):
        lists = []
        for cells, f in rows:
            cand = []
            for idx in range(16):
                if col[idx] != f:
                    continue
                if all(c is None or ((idx >> pos[perm[j]]) & 1) == c for j, c in enumerate(cells)):
                    cand.append(idx)
            lists.append(cand)
        def rec(i, used):                              # строки таблицы различны
            if i == len(lists):
                return True
            return any(c not in used and rec(i + 1, used | {c}) for c in lists[i])
        if rec(0, frozenset()):
            good.append("".join(perm))
    print(good[0] if len(good) == 1 else ("NONE" if not good else "AMBIGUOUS"))

main()

