#include <bits/stdc++.h>
using namespace std;
int col[16], k;
int cells[10][4], fv[10];
bool rec(int i, vector<vector<int>>& lists, set<int>& used) {
    if (i == (int)lists.size()) return true;
    for (int c : lists[i]) {
        if (used.count(c)) continue;
        used.insert(c);
        if (rec(i + 1, lists, used)) { used.erase(c); return true; }
        used.erase(c);
    }
    return false;
}
int main() {
    string s; cin >> s;
    for (int i = 0; i < 16; i++) col[i] = s[i] - '0';
    cin >> k;
    for (int i = 0; i < k; i++) {
        for (int j = 0; j < 4; j++) { string t; cin >> t; cells[i][j] = (t == "-") ? -1 : t[0] - '0'; }
        cin >> fv[i];
    }
    map<char,int> pos = {{'w',3},{'x',2},{'y',1},{'z',0}};
    string p = "wxyz"; vector<string> good;
    do {
        vector<vector<int>> lists(k);
        for (int r = 0; r < k; r++)
            for (int idx = 0; idx < 16; idx++) {
                if (col[idx] != fv[r]) continue;
                bool ok = true;
                for (int j = 0; j < 4; j++)
                    if (cells[r][j] != -1 && ((idx >> pos[p[j]]) & 1) != cells[r][j]) ok = false;
                if (ok) lists[r].push_back(idx);
            }
        set<int> used;
        if (rec(0, lists, used)) good.push_back(p);
    } while (next_permutation(p.begin(), p.end()));
    if (good.size() == 1) cout << good[0] << endl;
    else cout << (good.empty() ? "NONE" : "AMBIGUOUS") << endl;
}

